// Gmail OAuth e recuperação de senha (somente ambiente de testes)
const GOOGLE_CALLBACK='https://studio29-core-teste.studio29core.workers.dev/oauth/google/callback';
const OAUTH_COOKIE='studio29_oauth_state';
const b64url=bytes=>btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
const fromB64url=s=>Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-s.length%4)%4)),c=>c.charCodeAt(0));
async function aesKey(env){
 const raw=String(env.OAUTH_ENCRYPTION_KEY||'');
 if(!raw)throw Error('CHAVE_OAUTH_AUSENTE');
 const material=await crypto.subtle.digest('SHA-256',encoder.encode(raw));
 return crypto.subtle.importKey('raw',material,'AES-GCM',false,['encrypt','decrypt']);
}
async function encryptSecret(env,value){
 const iv=crypto.getRandomValues(new Uint8Array(12));
 const ct=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},await aesKey(env),encoder.encode(value)));
 return b64url(iv)+'.'+b64url(ct);
}
async function decryptSecret(env,value){
 const [iv,ct]=String(value||'').split('.');
 if(!iv||!ct)throw Error('TOKEN_CRIPTOGRAFADO_INVALIDO');
 return new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:fromB64url(iv)},await aesKey(env),fromB64url(ct)));
}
async function oauthState(env,nonce,userId){
 const key=await crypto.subtle.importKey('raw',encoder.encode(String(env.OAUTH_ENCRYPTION_KEY||'')),{name:'HMAC',hash:'SHA-256'},false,['sign']);
 const payload=b64url(encoder.encode(JSON.stringify({nonce,userId,ts:Date.now()})));
 const signature=b64url(new Uint8Array(await crypto.subtle.sign('HMAC',key,encoder.encode(payload))));
 return payload+'.'+signature;
}
async function validateState(env,state,nonce){
 const [payload,signature]=String(state||'').split('.');
 if(!payload||!signature||payload.length>1024)return null;
 const key=await crypto.subtle.importKey('raw',encoder.encode(String(env.OAUTH_ENCRYPTION_KEY||'')),{name:'HMAC',hash:'SHA-256'},false,['verify']);
 if(!(await crypto.subtle.verify('HMAC',key,fromB64url(signature),encoder.encode(payload))))return null;
 const parsed=JSON.parse(new TextDecoder().decode(fromB64url(payload)));
 if(parsed.nonce!==nonce||Date.now()-parsed.ts>600000||Date.now()<parsed.ts)return null;
 return parsed;
}
async function gmailAccess(env,db){
 const r=await db.prepare("SELECT * FROM integracoes_oauth WHERE provedor='google' AND ativo=1").first();
 if(!r?.token_atualizacao_criptografado)throw Error('GMAIL_NAO_CONFIGURADO');
 const refresh=await decryptSecret(env,r.token_atualizacao_criptografado);
 const res=await fetch('https://oauth2.googleapis.com/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:env.GOOGLE_CLIENT_ID,client_secret:env.GOOGLE_CLIENT_SECRET,refresh_token:refresh,grant_type:'refresh_token'})});
 const data=await res.json();
 if(!res.ok||!data.access_token)throw Error('GMAIL_TOKEN_INDISPONIVEL');
 return {accessToken:data.access_token,email:r.conta_email};
}
async function sendRecovery(env,db,email,link){
 const auth=await gmailAccess(env,db);
 if(!auth.email)throw Error('GMAIL_EMAIL_AUSENTE');
 const subject='STUDIO29 CORE - Recuperação de senha';
 const subjectEncoded='=?UTF-8?B?'+btoa(String.fromCharCode(...encoder.encode(subject)))+'?=';
 const body=[
  'STUDIO29 CORE','',
  'Recebemos uma solicitação de recuperação de senha.','',
  'Para definir uma nova senha, acesse:',link,'',
  'Este link é válido por 15 minutos.','',
  'Se você não solicitou a recuperação, ignore esta mensagem.','',
  'STUDIO29 Creative & Digital','Ideias que ganham vida'
 ].join('\r\n');
 const raw=[
  'From: '+auth.email,
  'To: '+email,
  'Subject: '+subjectEncoded,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset=UTF-8',
  'Content-Transfer-Encoding: base64',
  '',
  btoa(String.fromCharCode(...encoder.encode(body)))
 ].join('\r\n');
 const result=await fetch('https://gmail.googleapis.com/gmail/v1/users/me/messages/send',{
  method:'POST',
  headers:{Authorization:'Bearer '+auth.accessToken,'Content-Type':'application/json'},
  body:JSON.stringify({raw:b64url(encoder.encode(raw))})
 });
 if(!result.ok){
  console.error('GMAIL_API_ERRO_HTTP',result.status);
  throw Error('GMAIL_ENVIO_FALHOU_HTTP_'+result.status);
 }
 console.log('GMAIL_ENVIO_ACEITO',result.status);
}

// Limite por identificador normalizado; o hash impede armazenar e-mails em texto claro.
const LOGIN_WINDOW_MS=15*60*1000;
const LOGIN_MAX_FAILURES=5;
const LOGIN_INVALID={erro:'CREDENCIAIS_INVALIDAS'};

async function loginLimit(db,key){
 const row=await db.prepare('SELECT quantidade,janela_inicia_em,bloqueado_ate FROM tentativas_acesso WHERE identificador=?').bind(key).first();
 if(!row)return false;
 return Boolean(row.bloqueado_ate&&row.bloqueado_ate>now());
}

async function loginFailure(db,key,user){
 const timestamp=now();
 const windowStart=new Date(Date.now()-LOGIN_WINDOW_MS).toISOString();
 const lockUntil=future(LOGIN_WINDOW_MS);
 // Um único UPSERT incrementa a contagem, evitando perda de incrementos simultâneos.
 await db.prepare(`
  INSERT INTO tentativas_acesso(identificador,quantidade,janela_inicia_em,bloqueado_ate)
  VALUES(?,1,?,NULL)
  ON CONFLICT(identificador) DO UPDATE SET
   quantidade=CASE
    WHEN tentativas_acesso.janela_inicia_em<? THEN 1
    ELSE tentativas_acesso.quantidade+1
   END,
   janela_inicia_em=CASE
    WHEN tentativas_acesso.janela_inicia_em<? THEN excluded.janela_inicia_em
    ELSE tentativas_acesso.janela_inicia_em
   END,
   bloqueado_ate=CASE
    WHEN tentativas_acesso.janela_inicia_em<? THEN NULL
    WHEN tentativas_acesso.quantidade+1>=? THEN ?
    ELSE tentativas_acesso.bloqueado_ate
   END
 `).bind(key,timestamp,windowStart,windowStart,windowStart,LOGIN_MAX_FAILURES,lockUntil).run();
 const state=await db.prepare('SELECT quantidade,bloqueado_ate FROM tentativas_acesso WHERE identificador=?').bind(key).first();
 if(user){
  await db.prepare('UPDATE usuarios SET tentativas_login=?,atualizado_em=? WHERE id=?').bind(state.quantidade,timestamp,user.id).run();
  await audit(db,user.id,null,state.bloqueado_ate&&state.bloqueado_ate>timestamp?'LOGIN_LIMITE_ATINGIDO':'LOGIN_FALHOU');
 }else{
  await audit(db,null,null,'LOGIN_FALHOU');
 }
 return Boolean(state.bloqueado_ate&&state.bloqueado_ate>timestamp);
}

